	L["BarTextInstructions2"] = "Für bedingte Darstellung (nur wenn $VARIABLE aktiv/nicht Null):\n    {$VARIABLE}[$VARIABLE ist TRUE output]\n\n" -- For conditional display (only if $VARIABLE is active/non-zero):\n    {$VARIABLE}[$VARIABLE is TRUE output]\n\n
	L["BarTextInstructions3"] = "Boolean AND (&), OR (|), NOT (!), und Klammern werden für die bedingte Darstellung unterstützt:\n    {$A&$B}[Beide sind TRUE output]\n    {$A|$B}[Eine oder beide sind TRUE output]\n    {!$A}[$A ist FALSE output]\n    {!$A&($B|$C)}[$A ist FALSE und $B oder $C ist TRUE output]\n\n" -- Boolean AND (&), OR (|), NOT (!), and parenthises in logic for conditional display is supported:\n    {$A&$B}[Both are TRUE output]\n    {$A|$B}[One or both is TRUE output]\n    {!$A}[$A is FALSE output]\n    {!$A&($B|$C)}[$A is FALSE and $B or $C is TRUE output]\n\n
	L["BarTextInstructions4"] = "Ausdrücke (+, -, *, /) und Vergleichssymbole (>, >=, <, <=, =, !=) werden auch unterstützt:\n    {$VARIABLE*2>=$OTHERVAR}[$VARIABLE ist mindestens doppelt so groß wie $OTHERVAR output]\n\n" -- Expressions are also supported (+, -, *, /) and comparison symbols (>, >=, <, <=, =, !=):\n    {$VARIABLE*2>=$OTHERVAR}[$VARIABLE is at least twice as large as $OTHERVAR output]\n\n
	L["BarTextInstructions5"] = "IF/ELSE wird unterstützt:\n    {$VARIABLE}[$VARIABLE ist TRUE output][$VARIABLE ist FALSE output]\n    {$VARIABLE>2}[$VARIABLE ist größer als 2 output][$VARIABLE ist kleiner als 2 output]\n\n" -- IF/ELSE is supported:\n    {$VARIABLE}[$VARIABLE is TRUE output][$VARIABLE is FALSE output]\n    {$VARIABLE>2}[$VARIABLE is more than 2 output][$VARIABLE is less than 2 output]\n\n
	L["BarTextInstructions6"] = "IF/ELSE unterstützt NOT:\n    {!$VARIABLE}[$VARIABLE ist FALSE output][$VARIABLE ist TRUE output]\n\n" -- IF/ELSE includes NOT support:\n    {!$VARIABLE}[$VARIABLE is FALSE output][$VARIABLE is TRUE output]\n\n
